import {applyGraphics,graphicsMarkup} from './graphics.js?v=197';
import {musicMarkup} from './music.js?v=197';
import * as E from './engine.js?v=197';
import {COUNTRIES,COUNTRY,TECH} from './data.js?v=197';
import {proofTitle} from './intelligence.js?v=197';
import {esc,button,portrait,icon} from './ui.js?v=197';
const PREF='sigma2040-feedback-settings';
let prefs={sound:false,volume:25,motion:'system'};
try{const saved=JSON.parse(localStorage.getItem(PREF)||'{}');prefs={sound:saved.sound===true,volume:Number.isFinite(saved.volume)?Math.min(100,Math.max(0,saved.volume)):25,motion:['system','reduced'].includes(saved.motion)?saved.motion:'system'};}catch{}
let baseline=null,notices=[],resourceChanges={},agentChanges={},expires=0,audioContext=null,lastSound=0;
const signed=n=>(n>0?'+':'−')+Math.abs(Math.round(n*100)/100);
export function feedbackSnapshot(s){const f=s.factions[s.player];return {campaign:`${s.seed}:${s.player}`,turn:s.turn,log:s.logId,resources:{budget:f.budget,confidence:f.confidence,score:f.score,crisis:s.crisis},agents:Object.fromEntries(s.agents.filter(a=>a.faction===s.player).map(a=>[a.id,{name:a.name,energy:100-a.fatigue,exposure:a.exposure,status:a.status}])),proofs:Object.fromEntries(f.evidence.map(e=>[e.id,e.contested?'discarded':e.verified?'verified':'pending']))};}
export function feedbackDiff(before,after){
 const resources={},agents={},proofs=[],alerts=[];if(!before||before.campaign!==after.campaign)return {resources,agents,proofs,alerts};
 for(const [k,v] of Object.entries(after.resources))if(v!==before.resources[k])resources[k]=v-before.resources[k];
 for(const [id,a] of Object.entries(after.agents)){const old=before.agents[id];if(!old)continue;const energy=a.energy-old.energy,exposure=a.exposure-old.exposure;if(energy||exposure)agents[id]={energy,exposure};const previous=E.exposurePenalty(old),penalty=E.exposurePenalty(a);if(penalty>previous)alerts.push({kind:'exposure',agentId:id,text:`${a.name} · seuil d’exposition franchi à ${a.exposure}/100 : −${penalty} points aux passages clandestins, arrestations et extractions.`});if(a.status!==old.status&&['captured','dead','injured'].includes(a.status))alerts.push({kind:'condition',agentId:id,status:a.status,text:`${a.name} · ${a.status==='captured'?'capturé : organiser une extraction.':a.status==='dead'?'décédé : un poste est vacant.':'blessé : soins au QG recommandés.'}`});}
 for(const [id,status] of Object.entries(after.proofs))if(before.proofs[id]!==status)proofs.push({id,status,fresh:!before.proofs[id]});
 return {resources,agents,proofs,alerts};
}
export function resetExperience(){baseline=null;notices=[];resourceChanges={};agentChanges={};}
export function trackExperience(s){const next=feedbackSnapshot(s),old=baseline,diff=feedbackDiff(baseline,next);baseline=next;
 if(Object.keys(diff.resources).length||Object.keys(diff.agents).length||old&&old.turn!==next.turn){resourceChanges=diff.resources;agentChanges=diff.agents;expires=Date.now()+7000;}
 const added=diff.proofs.map(p=>{const proof=s.proofs.find(e=>e.id===p.id);return {key:'proof:'+p.id,kind:'proof',proofId:p.id,status:p.status,turn:s.turn,text:`${p.status==='verified'?'Preuve vérifiée':p.status==='discarded'?'Pièce écartée': 'Nouvelle pièce · à vérifier'} — ${proofTitle(proof)}`};});
 for(const a of diff.alerts)added.push({...a,key:a.kind+':'+a.agentId,turn:s.turn});
 for(const item of added){notices=notices.filter(n=>n.key!==item.key);notices.push(item);}
 notices=notices.filter(n=>n.kind!=='proof'||s.factions[s.player].evidence.some(e=>e.id===n.proofId)).slice(-16);
 const incoming=old?E.visibleLogs(s).filter(l=>l.id>old.log):[];if(diff.alerts.length||incoming.some(l=>l.type==='danger'))playCue('alert');else if(diff.proofs.length||incoming.some(l=>l.type==='clue'))playCue('discovery');
}
export function dismissNotices(){notices=[];}
export function evidenceFreshness(id){const n=notices.find(n=>n.proofId===id);return n?`<span class="proof-update">${n.status==='pending'?'NOUVELLE PIÈCE':n.status==='verified'?'VÉRIFICATION TERMINÉE':'PIÈCE ÉCARTÉE'}</span>`:'';}
export function feedbackNotices(){return notices.length?`<details class="feedback-notices"><summary>${icon('radar')} ${notices.length} nouveauté${notices.length>1?'s':''} à consulter${notices.some(n=>n.kind!=='proof')?' · Attention requise':''}</summary><div class="feedback-notice-list">${notices.map(n=>`<article class="feedback-notice ${n.kind==='proof'?'':'attention'}"><div><small class="activity-meta">Reçu au tour ${n.turn}</small><p>${esc(n.text)}</p></div>${n.kind==='proof'?button('Ouvrir la pièce','proof','small',`data-id="${esc(n.proofId)}"`):n.status==='dead'?button('Recruter un remplaçant','recruit','small'):button('Voir le dossier','select-agent','small',`data-id="${esc(n.agentId)}"`)}</article>`).join('')}${button('Marquer comme consulté','dismiss-feedback','small')}</div></details>`:'';}
export function paintResourceFeedback(){
 if(Date.now()>expires)return;
 const targets={budget:'[data-resource="budget"]',confidence:'[data-resource="confidence"]',score:'[data-resource="score"]',crisis:'[data-resource="crisis"]'};
 for(const [key,value] of Object.entries(resourceChanges)){const node=document.querySelector(targets[key]);if(!node)continue;appendDelta(node,value,key==='crisis',key==='confidence'?' confiance':'');}
 for(const [id,change] of Object.entries(agentChanges)){for(const card of document.querySelectorAll('.agent-card'))if(card.dataset.id===id&&change.energy)appendDelta(card.querySelector('.fatigue,.compact-energy'),change.energy,false,' énergie');}
}
function appendDelta(node,value,inverse,label){if(!node||node.querySelector(`[data-delta-label="${label}"]`))return;const tag=document.createElement('span');tag.className='resource-delta '+((value>0)!==inverse?'good':'danger');tag.dataset.deltaLabel=label;tag.textContent=signed(value)+label;node.append(tag);setTimeout(()=>tag.remove(),Math.max(0,expires-Date.now()));}
export function reportUpdates(s,scope='all'){const labels={budget:'crédits (solde du tour)',confidence:'confiance',score:'prestige',crisis:'crise'};return `<div class="report-updates"><div class="result-effects">${Object.entries(resourceChanges).filter(([k])=>scope==='all'||(scope==='world'?k==='crisis':k!=='crisis')).map(([k,v])=>`<span class="effect ${(v>0)!==(k==='crisis')?'good':'danger'}">${signed(v)} ${labels[k]}</span>`).join('')}</div>${notices.filter(n=>scope!=='world'&&n.turn===s.turn).map(n=>`<p class="${n.kind==='proof'?'':'attention'}">${esc(n.text)}</p>`).join('')}</div>`;}
export function activityLinks(s,l){
 const links=[];const own=s.agents.filter(a=>a.faction===s.player).find(a=>l.text.includes(a.name));if(own)links.push({cmd:'select-agent',id:own.id,label:'Dossier '+own.name});
 const target=E.knownTargets(s).find(t=>l.text.includes(t.name));if(target)links.push({cmd:'suspect',id:target.id,label:'Dossier '+target.name});
 const country=COUNTRIES.find(c=>l.text.includes(c.city));if(country)links.push({cmd:'map-country',id:country.id,label:country.city});
 return links;
}
export function activityRows(s,logs,compact=false){return logs.map(l=>{const a=s.agents.filter(a=>a.faction===s.player).find(a=>l.text.includes(a.name)),links=activityLinks(s,l),tone=['danger','warning'].includes(l.type)?'attention':l.type==='clue'?'discovery':'';return `<article class="activity-row ${tone} ${compact?'compact':''}"><div class="activity-avatar">${a?portrait(a):icon(l.type==='clue'?'file':l.type==='move'?'plane':l.type==='score'?'seal':'radar')}</div><div class="activity-copy"><span class="activity-meta">Tour ${l.turn} · ${l.faction?'Unité':'Mondial'}${l.type==='danger'?' · ALERTE':l.type==='clue'?' · RENSEIGNEMENT':''}</span><p>${esc(l.text)}</p>${links.length?`<div class="activity-links">${links.map(x=>button(x.label,x.cmd,'small',`data-id="${esc(x.id)}"`)).join('')}</div>`:''}</div></article>`;}).join('');}
export function transmission(r){
 if(r.condition==='dead'||r.condition==='captured')return '';
 if(r.condition==='injured')return 'Je suis blessé. Besoin de soins dès le retour.';
 if(r.status==='INTERROMPUE')return 'La situation a changé. En attente de nouveaux ordres.';
 if(r.status==='ÉCHEC')return r.agentId==='p15'?'Ça bloque. Il me faut une autre approche.':'Opération compromise. Je n’ai pas obtenu le résultat attendu.';
 const specific={travel:'Sur place. Liaison établie.',sneak:'Passage effectué. Je suis sur place, exposition remise à zéro.',rest:'Repos terminé. Prêt pour la suite.',fieldRest:'Repos terminé. Je reprends la liaison.',heal:'Soins terminés. Prêt à reprendre.',hide:'Profil bas terminé. Liaison rétablie.',findSafehouse:'Planque trouvée. Je peux récupérer ici.',arrest:'Cible en détention.',rescue:'Extraction réussie. Notre agent est libre.'};
 if(specific[r.type])return specific[r.type];
 const lines={p25:['Rapport transmis. Personne n’a posé de questions.','Mission terminée. La voie est libre.'],p26:['Compte rendu transmis. Je reste sur place.','Mission terminée. L’équipe peut compter sur moi.'],p23:['Rapport transmis. Les prochaines étapes sont prêtes.','Opération terminée. Je prépare la suite.'],p24:['Compte rendu envoyé. On fait le point ensemble.','Mission terminée. Je reste à l’écoute.'],p22:['Rapport transmis. Les indices concordent.','Mission terminée. Je reste sur la piste.'],p21:['Compte rendu transmis. Nos interlocuteurs attendent la suite.','Mission terminée. Les dispositions nécessaires ont été prises.'],p20:['Rapport envoyé. Tout est sous contrôle.','Opération terminée. Je reste en veille.'],p19:['Livraison effectuée. Les détails sont dans mon rapport.','Objectif atteint. Je garde un œil sur la route.'],p0:['Compte rendu transmis. À vous de jouer.','Résultat confirmé. Je reste à votre disposition.'],p12:['Compte rendu envoyé. Quelle est la suite ?','Objectif de mission atteint.'],p13:['C’est fait. Le résultat est dans le dossier.','Compte rendu transmis. On passe à la suite ?'],p14:['Terminé. En attente.','Mission accomplie.'],p15:['Rapport envoyé. Tout est dedans.','Terminé. Je reste joignable sur le canal.'],p18:['Affaire réglée. Vous trouverez les détails dans mon rapport.','Compte rendu envoyé. Je reste en contact.'],p17:['Rapport transmis. Les faits sont dans le dossier.','Opération terminée. Je prépare la suite.'],p16:['Résultat transmis. Je reste attentive.','Compte rendu envoyé au commandement.']};
 const choices=lines[r.agentId]||['Compte rendu transmis.','Opération terminée. En attente des ordres.'];return choices[r.turn%choices.length];
}
export function applyPreferences(){applyGraphics();if(typeof document==='undefined')return;document.documentElement.classList.toggle('reduce-feedback',prefs.motion==='reduced');}
export function updatePreference(key,value){if(key==='sound')prefs.sound=!!value;if(key==='volume')prefs.volume=Math.max(0,Math.min(100,Number(value)||0));if(key==='motion')prefs.motion=value==='reduced'?'reduced':'system';try{localStorage.setItem(PREF,JSON.stringify(prefs));}catch{}applyPreferences();}
export function settingsMarkup(){return `${graphicsMarkup()}${musicMarkup()}<section class="feedback-settings"><h3>Sons et animations</h3><label class="feedback-toggle"><input id="feedbackSound" type="checkbox" ${prefs.sound?'checked':''}> Sons de transmission et d’alerte</label><label for="feedbackVolume">Volume des effets <output id="feedbackVolumeValue">${prefs.volume}%</output></label><input id="feedbackVolume" type="range" min="0" max="100" value="${prefs.volume}" ${prefs.sound?'':'disabled'}><label for="feedbackMotion">Animations</label><select id="feedbackMotion"><option value="system" ${prefs.motion==='system'?'selected':''}>Suivre les préférences de l’appareil</option><option value="reduced" ${prefs.motion==='reduced'?'selected':''}>Réduire les animations</option></select><p>Les informations restent visibles lorsque les effets sont réduits. Réglages conservés sur cet appareil.</p>${button('Écouter un signal','test-sound','small',prefs.sound?'':'disabled title="Activez les sons pour écouter un signal."')}</section>`;}
export function playCue(kind='transmission'){
 if(!prefs.sound||prefs.volume===0||typeof window==='undefined'||document.hidden||Date.now()-lastSound<300)return;
 try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;audioContext??=new Audio();if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});lastSound=Date.now();const notes=kind==='alert'?[420,300]:kind==='discovery'?[650,880,1050]:[620,790],now=audioContext.currentTime;notes.forEach((hz,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain(),start=now+i*.1;osc.type='sine';osc.frequency.value=hz;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(prefs.volume/100*.11,start+.015);gain.gain.exponentialRampToValueAtTime(.0001,start+.13);osc.connect(gain);gain.connect(audioContext.destination);osc.start(start);osc.stop(start+.15);osc.onended=()=>{osc.disconnect();gain.disconnect();};});}catch{}
}

export function techUnavailable(s,id){return s.ended?'Campagne terminée.':E.getTechSlots(s,s.player)>=2?'Les deux modules sont occupés.':s.factions[s.player].budget<TECH[id].cost?`Il manque ${TECH[id].cost-s.factions[s.player].budget} crédit(s).`:'';}
